$content = $content -replace "className=`"relative overflow-hidden px-8 py-3\.5 bg-neutral-900 border border-neutral-900 text-white text-xs font-bold tracking-\[0\.15em\] uppercase rounded-full shadow-xl flex items-center justify-center gap-3 group transition-colors duration-300`"", "className=`"relative overflow-hidden px-8 py-3.5 bg-white/30 backdrop-blur-xl border border-white/50 text-neutral-900 text-xs font-bold tracking-[0.15em] uppercase rounded-full shadow-[0_8px_32px_0_rgba(31,38,135,0.07)] flex items-center justify-center gap-3 group transition-all duration-500 hover:bg-white/50`""
$content = $content -replace "className=`"relative overflow-hidden px-8 py-3\.5 text-neutral-900 bg-transparent text-xs font-bold tracking-\[0\.15em\] uppercase rounded-full border border-black/20 group hover:border-black transition-all duration-300`"", "className=`"relative overflow-hidden px-8 py-3.5 text-neutral-700 bg-white/10 backdrop-blur-md text-xs font-bold tracking-[0.15em] uppercase rounded-full border border-white/30 group hover:border-neutral-400 hover:bg-white/30 transition-all duration-500 shadow-[0_8px_32px_0_rgba(31,38,135,0.03)]`""
$content = $content -replace "group-hover:text-white`"","group-hover:text-black`""
Set-Content -Path "components/Hero.tsx" -Value $content
